  text-align: center; background: radial-gradient(circle, rgba(255,0,0,.35), transparent 38rem), linear-gradient(135deg, #260000, #090909);
  border-top: 1px solid rgba(255,0,0,.45); border-bottom: 1px solid rgba(255,0,0,.45);
