.country.open .country-menu { display:block; }
.schedule { width: 100%; border-collapse: collapse; overflow: hidden; background: #111; border: 1px solid var(--line); }
.schedule th, .schedule td { padding: 1.1rem; text-align: left; border-bottom: 1px solid var(--line); }
.schedule th { background: var(--red); text-transform: uppercase; letter-spacing: .12em; font-size: .82rem; }
.schedule tr:hover td { background: rgba(255,0,0,.08); }
.toggle-wrap { display: inline-flex; padding: .35rem; border: 1px solid var(--line); background: #080808; margin: 1rem 0 2rem; }
.toggle-wrap button { border: 0; color: #fff; background: transparent; padding: .9rem 1.2rem; cursor: pointer; text-transform: uppercase; font-weight: 950; letter-spacing: .1em; }
.toggle-wrap button.selected { background: var(--red); }
.toggle-panel { opacity: 1; transform: translateY(0); transition: opacity .25s ease, transform .25s ease; }
.filter-bar { display: flex; gap: 1rem; align-items:center; justify-content: space-between; flex-wrap: wrap; margin-bottom: 2rem; }
.filter-bar select { background: #111; color:#fff; border:1px solid var(--line); padding: .9rem 1rem; min-width: 240px; }
.instructor-card { min-height: 360px; display:flex; flex-direction: column; justify-content: flex-end; background: linear-gradient(transparent, rgba(0,0,0,.9)), var(--photo), #1a1a1a; background-size: cover; background-position: center; }
.instructor-card[hidden] { display:none; }
.location { color: var(--red); text-transform: uppercase; font-weight: 950; letter-spacing: .12em; font-size: .82rem; }
.faq { border-top: 1px solid var(--line); }
.faq-item { border-bottom: 1px solid var(--line); }
.faq-q { width: 100%; background: transparent; color: #fff; border: 0; padding: 1.4rem 0; display:flex; justify-content:space-between; gap:1rem; text-align:left; cursor:pointer; font-family: Oswald, Impact, sans-serif; text-transform:uppercase; font-size: clamp(1.35rem, 3vw, 2.2rem); }
.faq-a { display: none; max-width: 800px; padding: 0 0 1.6rem; }
.faq-item.open .faq-a { display:block; }
.faq-item.open .faq-q span { color: var(--red); }
.feature-row { display:grid; grid-template-columns: .9fr 1.1fr; gap: 1rem; align-items: stretch; }
.feature-row .card { min-height: 210px; }
.marquee { overflow:hidden; border-block: 1px solid rgba(255,0,0,.5); background:#0a0a0a; }
