from pathlib import Path
from html.parser import HTMLParser
root=Path('/app/output')
files=['index.html','the-workout.html','instructors.html','ride-faq.html','digital-platform.html']
required={
 'index.html':['TRY THE BEST WORKOUT IN THE WORLD','JOIN US FOR A FREE 30 DAY TRIAL','Life in the Red'],
 'the-workout.html':['Tuesday','Full Body (Lower Focus)','Monday','Chest &amp; Back','Thursday','Arms &amp; Abs','Start on the Floor or the Treadmill'],
 'instructors.html':['New York','Los Angeles','London','Miami','San Francisco','Dani Reyes'],
 'ride-faq.html':['What is RIDE x LIFT?','What should I wear?','Do I need cycling shoes?','How long is the class?'],
 'digital-platform.html':['World Class Workouts On Your Time','Unlimited Access','30 Day Free Trial','Anytime, Anywhere']
}
class Parser(HTMLParser):
    def error(self, message): raise AssertionError(message)
for name in files:
    path=root/name
    text=path.read_text()
    Parser().feed(text)
    for item in required[name]:
        if item not in text:
            raise SystemExit(f'Missing {item!r} in {name}')
    for link in ['assets/styles.css','assets/app.js']:
        if link in text and not (root/link).exists():
            raise SystemExit(f'Missing asset {link}')
print('HTML parse and required content checks passed for', ', '.join(files))
